#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000066.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'488596': 'Complete Kazan Mother-and-Child panel with evangelists in four corners and small side saints. Full board edges and surrounding neutral background retained; gold and red fields match native description.', '498308': 'Full rectangular painted Coronation icon: Mary kneeling between seated Father and Son, dove above, red seraphs below. Complete border and museum hanging cord above preserved. No crop or separate-scene substitution.', '498323': 'Complete dark rectangular Saint Nicholas panel with open Gospel, raised blessing hand, two small side medallions and gold halo. Surface wear and full edges retained; no claim to read small inscriptions.', '498356': 'Full cast plaque with three standing Church Fathers, rectangular beaded frame and openwork top with Christ and angels. All projections and neutral background retained; one physical cast.', '498591': 'Complete cast icon with two mounted saints, blue/green/white enamel and upper Trinity medallion. Outer frame and upper loop shape fully visible; exact individual inventory, not another casting.', '498644': 'Full gilded John the Baptist panel with long hair, green mantle, pointing hand, bowl with Child and lower scroll. Entire border and worn gilded background retained. Partial repainting statement preserved as source evidence.', '498654': 'Whole surviving arched Last Supper panel with Christ and apostles around a cloth-covered table. Arch, lower border and neutral background all included. Probable former iconostasis origin does not create an additional artwork.', '498699': 'Whole dark painted Pieta-type icon: Mother holds small dead Christ, gold halo, low masonry foreground and ornamental border. Matches unusual source title/description without replacing it with a more generic title. Complete board outline retained.', '498705': 'Whole brown-bordered Ascension icon: central Virgin flanked by angels and apostles below Christ in mandorla with two angels. Full thick panel edges and neutral background retained. Qualified Moscow school/Old Believer attribution preserved.', '499397': 'Full enamelled cast Saint Antipas icon with blessing hand, closed book, small Deesis figures above, floral blue/green frame and intact upper tab. Counts one inventory object; all supplied edges visible.', '499478': 'Complete small bronze Nativity cast with top suspension bead and surrounding inscription. Reclining Virgin, manger and lower figures visible. Full supplied obverse and silhouette retained; no assertion of reverse-side visual review.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Individual actual derivative viewed; complete supplied museum composition and native inventory association accepted.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==11
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. Originals decoded and hashed; derivatives individually visually viewed.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('11 actual per-image visual decisions and complete file checks saved')
